const PERSONNEL_STATUS_PLAN = { 'on-duty': 42, 'in-field': 6, 'at-base': 6, 'on-leave': 6 };
const PERSONNEL_STATION_PLAN = { Bharati: 26, Maitri: 20, Himadri: 14 };

function planPersonnel() {
  const rand = mulberry32(20260905);
  const stationPlan = [];
  for (const [name, weight] of Object.entries(PERSONNEL_STATION_PLAN)) {
    for (let i = 0; i < weight; i += 1) stationPlan.push(name);
  }
  const statusPlan = [];
  for (const [status, count] of Object.entries(PERSONNEL_STATUS_PLAN)) {
    for (let i = 0; i < count; i += 1) statusPlan.push(status);
  }
  shuffleInPlace(stationPlan, rand);
  shuffleInPlace(statusPlan, rand);

  const coordsByName = {};
  for (const station of STATIONS) coordsByName[station.name] = station.location.coordinates; // [lng, lat]

  return PERSONNEL_NAMES.map((name, i) => {
    const status = statusPlan[i];
    const station = stationPlan[i];
    const role = PERSONNEL_ROLES[i % PERSONNEL_ROLES.length];

    // A few people rotate out inside the next 30 days (for the timeline demo);
    // everyone else is comfortably mid-rotation.
    const daysToEnd = i < 4 ? randInt(rand, 2, 29) : randInt(rand, 45, 340);
    const rotationEnd = daysFromNowIso(daysToEnd);
    const rotationStart = daysFromNowIso(daysToEnd - randInt(rand, 150, 210)); // ~5–7 months prior

    let currentLocation = null;
    if (status === 'in-field') {
      const [lng, lat] = coordsByName[station];
      const dLat = (rand() - 0.5) * 0.5;
      const dLng = (rand() - 0.5) * 0.5;
      currentLocation = { type: 'Point', coordinates: [lng + dLng, lat + dLat] }; // near-station field camp
    }

    return { name, role: role.role, quals: role.quals, status, station, rotationStart, rotationEnd, currentLocation };
  });
}

